// 4D 野心評估模型自檢函式與決策期望值計算
function evaluateAmbition({ speed, height, depth, breadth, pSuccess, vBreakthrough }) {
  // 失敗成本在 AI 提問情境趨近於 0
  const cFailure = 0;
  const expectedValue = (pSuccess * vBreakthrough) - ((1 - pSuccess) * cFailure);

  return {
    expectedValue: expectedValue,
    verdict: expectedValue > 0 ? '數學期望值為正，大膽提出大問題！' : '請重新檢視目標',
    checklist: {
      speed: '是否已將日常流程自動化縮短時間？',
      height: '是否跳出微觀管理，透過「然後呢？」四層階梯直擊最終結果？',
      depth: '是否連問 4 個專家診斷問題並設定極限高標？',
      breadth: '是否將名詞換成動詞作用，跨界借調最強解法？'
    }
  };
}

// 模型選型帕累托效益與每月 API 成本預算估算函式
function calculateMonthlyLLMCost({
  inputPricePerMillion,
  outputPricePerMillion,
  dailyRequests,
  avgInputTokens = 800,
  avgOutputTokens = 300
}) {
  const dailyInputCost = (dailyRequests * avgInputTokens / 1_000_000) * inputPricePerMillion;
  const dailyOutputCost = (dailyRequests * avgOutputTokens / 1_000_000) * outputPricePerMillion;
  const monthlyCost = (dailyInputCost + dailyOutputCost) * 30;

  return {
    dailyCostUSD: Number((dailyInputCost + dailyOutputCost).toFixed(4)),
    monthlyCostUSD: Number(monthlyCost.toFixed(2)),
    isCostEffective: monthlyCost < 100 ? '✅ 成本極具競爭力（推薦用於大量產線）' : '⚠️ 成本偏高（建議僅限關鍵複雜決策）'
  };
}

// 6:30 時鐘指針幾何角度計算程式（破除 AI 擴散生圖兩針重疊之物理常識錯誤）
function calculateClockAngles(hours, minutes) {
  // 分針每分鐘走 6 度 (360 / 60)
  const minuteAngle = minutes * 6;
  // 時針每小時走 30 度，每分鐘走 0.5 度 (360 / 12 = 30, 30 / 60 = 0.5)
  const hourAngle = (hours % 12) * 30 + minutes * 0.5;

  return {
    time: `${hours}:${minutes < 10 ? '0' : ''}${minutes}`,
    hourHandAngle: hourAngle,      // 6:30 時為 195 度（處於 6 與 7 正中間）
    minuteHandAngle: minuteAngle,  // 6:30 時為 180 度（指向 6 正下方）
    explanation: '時針絕不可與分針重疊在 180 度，必須位在 195 度！'
  };
}
